/*
 * Conformance harness (area graphics, spec S-043): hand-written parts of the tracing fake backend.
 *
 * The real libobs/graphics/graphics.c and graphics-imports.c are linked.  os_dlopen()/os_dlsym() hand
 * graphics-imports.c a table of fake device functions (graphics_backend_gen.c, generated by
 * scripts/graphics/gen_backend.py: a trace-only implementation for every export, whose results come from
 * the "ret"/"fail" tables) plus the functions below that model a little state (textures, buffers, viewport,
 * render targets...).  Every backend call prints one line starting with two spaces and "dev".
 *
 * A function is "hand written" when this file contains FAKE(name) for it; the generator skips those.
 * Test tooling, not part of libobs.
 */
#include <stdarg.h>
#include "script.h"
#include "graphics_backend.h"
#include "graphics/vec2.h"
#include "graphics/vec3.h"
#include "graphics/vec4.h"

/* ---------------- handles ---------------- */
#define MAXH 4096
static struct fh *handles[MAXH];
static int nhandles, next_id;

struct fh *fh_new(const char *kind)
{
	struct fh *h = bzalloc(sizeof(*h));
	h->id = ++next_id;
	snprintf(h->kind, sizeof(h->kind), "%s", kind);
	if (nhandles < MAXH)
		handles[nhandles++] = h;
	return h;
}
struct fh *fh_lookup(const void *p)
{
	for (int i = 0; p && i < nhandles; i++)
		if (handles[i] == p)
			return handles[i];
	return NULL;
}
int fh_id(const void *p)
{
	struct fh *h = fh_lookup(p);
	return h ? h->id : -1;
}
void fh_free(void *p)
{
	for (int i = 0; p && i < nhandles; i++)
		if (handles[i] == p) {
			struct fh *h = handles[i];
			handles[i] = handles[--nhandles];
			bfree(h->map);
			bfree(h);
			return;
		}
}
void fh_reset(void)
{
	while (nhandles) {
		struct fh *h = handles[--nhandles];
		bfree(h->map);
		bfree(h);
	}
	next_id = 0;
}

/* ---------------- tracing ---------------- */
int tr_enabled = 1;
void tr_begin(const char *name)
{
	if (tr_enabled)
		printf("  dev %s", name);
}
void tr_end(void)
{
	if (tr_enabled)
		putchar('\n');
}
void tr_raw(const char *fmt, ...)
{
	if (!tr_enabled)
		return;
	va_list ap;
	va_start(ap, fmt);
	vprintf(fmt, ap);
	va_end(ap);
}
void tr_str(const char *nm, const char *v)
{
	if (!tr_enabled)
		return;
	if (!v)
		printf(" %s=null", nm);
	else {
		printf(" %s=", nm);
		script_print_quoted(v);
	}
}
void tr_ptr(const char *nm, const void *v)
{
	if (!tr_enabled)
		return;
	if (!v)
		printf(" %s=null", nm);
	else if (fh_lookup(v))
		printf(" %s=#%d", nm, fh_id(v));
	else
		printf(" %s=ptr", nm);
}
void tr_bool(const char *nm, bool v)
{
	if (tr_enabled)
		printf(" %s=%s", nm, v ? "true" : "false");
}
void tr_dbl(const char *nm, double v)
{
	if (tr_enabled)
		printf(" %s=%.9g", nm, v);
}
void tr_u64(const char *nm, unsigned long long v)
{
	if (tr_enabled)
		printf(" %s=%llu", nm, v);
}
void tr_i64(const char *nm, long long v)
{
	if (tr_enabled)
		printf(" %s=%lld", nm, v);
}
void tr_fn(const char *nm, const void *v)
{
	if (tr_enabled)
		printf(" %s=%s", nm, v ? "fn" : "null");
}

/* ---------------- scripted results ---------------- */
struct kv {
	char *k, *v;
};
#define MAXKV 256
static struct kv rets[MAXKV], fails[MAXKV], missing[MAXKV];
static int nrets, nfails, nmissing;

static struct kv *kv_find(struct kv *t, int n, const char *k)
{
	for (int i = 0; i < n; i++)
		if (!strcmp(t[i].k, k))
			return &t[i];
	return NULL;
}
static void kv_set(struct kv *t, int *n, const char *k, const char *v)
{
	struct kv *e = kv_find(t, *n, k);
	if (!e) {
		e = &t[(*n)++];
		e->k = bstrdup(k);
	} else
		bfree(e->v);
	e->v = bstrdup(v);
}
static void kv_del(struct kv *t, int *n, const char *k)
{
	struct kv *e = kv_find(t, *n, k);
	if (!e)
		return;
	bfree(e->k);
	bfree(e->v);
	*e = t[--(*n)];
}
void fake_set_ret(const char *fn, const char *val)
{
	kv_set(rets, &nrets, fn, val);
}
void fake_set_fail(const char *fn, bool fail)
{
	if (fail)
		kv_set(fails, &nfails, fn, "1");
	else
		kv_del(fails, &nfails, fn);
}
void fake_set_missing(const char *fn, bool m)
{
	if (m)
		kv_set(missing, &nmissing, fn, "1");
	else
		kv_del(missing, &nmissing, fn);
}
bool fake_is_missing(const char *fn)
{
	return kv_find(missing, nmissing, fn) != NULL;
}

static struct {
	const char *fn, *val;
} defaults[] = {
	{"device_get_name", "FakeGL"},
	{"device_preprocessor_name", "_FAKE"},
	{"gpu_get_driver_version", "1.2.3"},
	{"gpu_get_renderer", "Fake Renderer"},
	{"device_get_type", "1"},
	{"gs_texture_map", "1"},
	{"gs_stagesurface_map", "1"},
	{"gs_timer_get_data", "1"},
	{"gs_get_adapter_count", "0"},
	{NULL, NULL},
};
static const char *lookup(const char *fn)
{
	struct kv *e = kv_find(rets, nrets, fn);
	if (e)
		return e->v;
	for (int i = 0; defaults[i].fn; i++)
		if (!strcmp(defaults[i].fn, fn))
			return defaults[i].val;
	return NULL;
}
bool ret_bool(const char *fn)
{
	const char *v = lookup(fn);
	return v && (!strcmp(v, "1") || !strcmp(v, "true"));
}
double ret_dbl(const char *fn)
{
	const char *v = lookup(fn);
	return v ? strtod(v, NULL) : 0.0;
}
const char *ret_str(const char *fn)
{
	const char *v = lookup(fn);
	return (v && strcmp(v, "-")) ? v : NULL;
}
long long ret_i64(const char *fn)
{
	const char *v = lookup(fn);
	return v ? strtoll(v, NULL, 0) : 0;
}
unsigned long long ret_u64(const char *fn)
{
	const char *v = lookup(fn);
	return v ? strtoull(v, NULL, 0) : 0;
}
static char *nth_fn;
static int nth_target, nth_count;
void fake_set_fail_nth(const char *fn, int n)
{
	bfree(nth_fn);
	nth_fn = bstrdup(fn);
	nth_target = n;
	nth_count = 0;
}
void *ret_ptr(const char *fn, const char *kind)
{
	if (kv_find(fails, nfails, fn))
		return NULL;
	if (nth_fn && !strcmp(nth_fn, fn) && ++nth_count == nth_target)
		return NULL;
	return fh_new(kind);
}

uint32_t fake_w = 1920, fake_h = 1080;
int fake_dump_full = 1;
static char *adapters[16];
static int nadapters;
void fake_add_adapter(const char *name)
{
	if (nadapters < 16)
		adapters[nadapters++] = bstrdup(name);
}
static struct kv files[64];
static int nfiles;
void fake_add_file(const char *path, const char *content)
{
	kv_set(files, &nfiles, path, content);
}
const char *fake_get_file(const char *path)
{
	struct kv *e = kv_find(files, nfiles, path);
	return e ? e->v : NULL;
}
void fake_reset_script(void)
{
	while (nrets)
		kv_del(rets, &nrets, rets[0].k);
	while (nfails)
		kv_del(fails, &nfails, fails[0].k);
	while (nmissing)
		kv_del(missing, &nmissing, missing[0].k);
	while (nfiles)
		kv_del(files, &nfiles, files[0].k);
	for (int i = 0; i < nadapters; i++)
		bfree(adapters[i]);
	nadapters = 0;
	fake_w = 1920;
	fake_h = 1080;
	fake_dump_full = 1;
}

/* ---------------- dl emulation ---------------- */
static int dl_marker;
void *os_dlopen(const char *path)
{
	return (path && !strncmp(path, "fake", 4)) ? &dl_marker : NULL;
}
void os_dlclose(void *module)
{
	(void)module;
	printf("  os_dlclose\n");
}
void *os_dlsym(void *module, const char *func)
{
	(void)module;
	if (fake_is_missing(func))
		return NULL;
	for (int i = 0; fake_symtab[i].name; i++)
		if (!strcmp(fake_symtab[i].name, func))
			return fake_symtab[i].fn;
	return NULL;
}
void gs_init_image_deps(void) {}
void gs_free_image_deps(void) {}

char *os_quick_read_utf8_file(const char *path)
{
	const char *c = fake_get_file(path);
	return c ? bstrdup(c) : NULL;
}

uint8_t *gs_create_texture_file_data(const char *file, enum gs_color_format *format, uint32_t *cx, uint32_t *cy)
{
	/* virtual image: file "WxH" (e.g. "3x2") yields an RGBA image, anything else fails */
	unsigned w, h;
	if (!file || sscanf(file, "%ux%u", &w, &h) != 2)
		return NULL;
	uint8_t *d = bmalloc((size_t)w * h * 4);
	for (size_t i = 0; i < (size_t)w * h * 4; i++)
		d[i] = (uint8_t)(i & 0xff);
	*format = GS_RGBA;
	*cx = w;
	*cy = h;
	return d;
}

