bool FAKE_device_enum_adapters(gs_device_t *device, bool (*callback)(void *, const char *, uint32_t), void *param) /* FAKE(device_enum_adapters) */
{
	(void)device;
	tr_begin("device_enum_adapters");
	tr_end();
	for (int i = 0; i < nadapters; i++)
		if (!callback(param, adapters[i], (uint32_t)i))
			break;
	return ret_bool("device_enum_adapters");
}

