/* Mapping: a zero-filled buffer of height*linesize bytes; the linesize is the "ret maplinesize" value or width*4. */
static bool do_map(struct fh *h, const char *nm, uint8_t **ptr, uint32_t *linesize)
{
	tr_begin(nm);
	tr_ptr("obj", h);
	tr_end();
	if (!ret_bool(nm))
		return false;
	h->linesize = ret_u64("maplinesize") ? (uint32_t)ret_u64("maplinesize") : h->w * 4;
	bfree(h->map);
	h->map = bzalloc((size_t)h->linesize * h->h + 1);
	*ptr = h->map;
	*linesize = h->linesize;
	return true;
}
static void do_unmap(struct fh *h, const char *nm)
{
	tr_begin(nm);
	tr_ptr("obj", h);
	if (tr_enabled && h->map) {
		printf(" bytes=");
		script_print_hex(h->map, (size_t)h->linesize * h->h);
	}
	tr_end();
}
bool FAKE_gs_texture_map(gs_texture_t *t, uint8_t **ptr, uint32_t *linesize) /* FAKE(gs_texture_map) */
{
	return do_map(H(t), "gs_texture_map", ptr, linesize);
}
void FAKE_gs_texture_unmap(gs_texture_t *t) /* FAKE(gs_texture_unmap) */
{
	do_unmap(H(t), "gs_texture_unmap");
}
