/* NV12 / P010 pairs */
static bool pair_create(const char *nm, gs_texture_t **y, gs_texture_t **uv, uint32_t w, uint32_t h, uint32_t flags)
{
	tr_begin(nm);
	tr_u64("w", w);
	tr_u64("h", h);
	tr_u64("flags", flags);
	tr_end();
	if (!ret_bool(nm))
		return false;
	struct fh *a = fh_new("tex"), *b = fh_new("tex");
	a->w = w, a->h = h, b->w = w / 2, b->h = h / 2;
	*y = (gs_texture_t *)a;
	*uv = (gs_texture_t *)b;
	return true;
}
bool FAKE_device_texture_create_nv12(gs_device_t *d, gs_texture_t **y, gs_texture_t **uv, uint32_t w, uint32_t h, /* FAKE(device_texture_create_nv12) */
				     uint32_t flags)
{
	(void)d;
	return pair_create("device_texture_create_nv12", y, uv, w, h, flags);
}
bool FAKE_device_texture_create_p010(gs_device_t *d, gs_texture_t **y, gs_texture_t **uv, uint32_t w, uint32_t h, /* FAKE(device_texture_create_p010) */
				     uint32_t flags)
{
	(void)d;
	return pair_create("device_texture_create_p010", y, uv, w, h, flags);
}

