/* shaders: scripted compile errors */
static gs_shader_t *shader_create(const char *nm, const char *text, const char *file, char **err)
{
	tr_begin(nm);
	tr_raw(" text_len=%zu", text ? strlen(text) : (size_t)0); /* the text itself is specified by S-020 */
	tr_str("file", file);
	tr_end();
	if (ret_str("shader_error") && err)
		*err = bstrdup(ret_str("shader_error"));
	return (gs_shader_t *)ret_ptr(nm, "shader");
}
gs_shader_t *FAKE_device_vertexshader_create(gs_device_t *d, const char *shader, const char *file, char **err) /* FAKE(device_vertexshader_create) */
{
	(void)d;
	return shader_create("device_vertexshader_create", shader, file, err);
}
